'use strict';
let currentUser=null,cloudRevision=0,dirty=false,syncing=false,syncConflict=false,syncTimer;
const legacyData=localStorage.getItem('zen-kanban-v1');
async function requestAPI(path,method='GET',body){
 const controller=new AbortController();
 const timer=setTimeout(()=>controller.abort(),20000);
 try{
  const r=await fetch('/api/'+path,{method,credentials:'same-origin',signal:controller.signal,headers:body?{'Content-Type':'application/json'}:{},body:body?JSON.stringify(body):undefined});
  const result=await r.json().catch(()=>({error:'Máy chủ trả về phản hồi không hợp lệ.'}));
  if(!r.ok)throw Object.assign(new Error(result.error||'Yêu cầu không thành công'),{status:r.status});
  return result;
 }catch(error){
  if(error.name==='AbortError')throw Object.assign(new Error('Kết nối quá thời gian chờ. Dữ liệu đã lưu tại thiết bị.'),{status:0});
  throw error;
 }finally{clearTimeout(timer);}
}
function authScreen(mode='login',message=''){document.body.classList.add('signed-out');document.querySelector('#auth-screen')?.remove();const screen=document.createElement('section');screen.id='auth-screen';const reset=mode==='reset',register=mode==='register',forgot=mode==='forgot',verify=mode==='verify';screen.innerHTML=`<div class="auth-story"><a class="auth-logo" href="/"><svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64" fill="none" aria-hidden="true"><defs><linearGradient id="auth-wisdom" x1="8" y1="12" x2="56" y2="54" gradientUnits="userSpaceOnUse"><stop stop-color="#7544b8"/><stop offset=".55" stop-color="#d76aa1"/><stop offset="1" stop-color="#ef9656"/></linearGradient></defs><rect x="2" y="2" width="60" height="60" rx="19" fill="url(#auth-wisdom)"/><path d="M10 33s8-13 22-13 22 13 22 13-8 13-22 13S10 33 10 33Z" stroke="white" stroke-width="2.6" stroke-linejoin="round"/><circle cx="32" cy="33" r="7.5" stroke="white" stroke-width="2.5"/><circle cx="32" cy="33" r="2.6" fill="white"/><path d="m32 10 2.4 4.4L32 18l-2.4-3.6L32 10Z" fill="white"/><path d="M21 15l2 3m20-3-2 3" stroke="white" stroke-width="2" stroke-linecap="round"/></svg><span class="auth-wordmark">kanban <small>ZEN STUDIO</small></span></a><span class="eyebrow">KHÔNG GIAN LÀM VIỆC CÁ NHÂN</span><h1>Gọn công việc.<br>Rộng tâm trí.</h1><p>Từ ý tưởng đầu tiên đến công việc hoàn thành.<br>Mọi dự án của bạn, luôn ở cùng một nơi.</p><div class="auth-mini"><span>Idea</span><span>List</span><span>Doing</span><span>Done ✓</span></div><small>Một sản phẩm thuộc Zen Studio <span class="auth-version">· v1.9.10</span></small></div><div class="auth-card"><span class="eyebrow">CHÀO MỪNG BẠN</span><h2>${register?'Tạo tài khoản':forgot?'Quên mật khẩu':reset?'Mật khẩu mới':verify?'Xác minh email':'Trở lại không gian của bạn'}</h2><p id="auth-message" role="status" tabindex="-1">${esc(message)}</p><form id="auth-form">${!reset&&!verify?field('Email','email','','email',true,254):''}${!forgot&&!verify?passwordField(register||reset):''}${!forgot&&!verify?'<p class="subtext">Mật khẩu từ 10 ký tự. Không dùng lại mật khẩu ở nơi khác.</p>':''}<button class="btn primary" type="submit">${register?'Tạo tài khoản':forgot?'Gửi liên kết khôi phục':reset?'Lưu mật khẩu':verify?'Xác minh email':'Đăng nhập'}</button></form><div class="auth-links"><button data-auth="login">Đăng nhập</button><button data-auth="register">Tạo tài khoản</button><button data-auth="forgot">Quên mật khẩu?</button></div><button id="resend-verify" class="text-btn">Gửi lại email xác minh</button><p class="auth-note">Dữ liệu riêng theo tài khoản · Đồng bộ giữa thiết bị<br>Dữ liệu cũ trên máy vẫn được giữ; có thể nhập sau khi đăng nhập.</p></div>`;document.body.append(screen);screen.querySelectorAll('[data-auth]').forEach(b=>b.onclick=()=>authScreen(b.dataset.auth));screen.querySelector('.password-eye')?.addEventListener('click',e=>{const button=e.currentTarget,input=screen.querySelector('[name=password]'),visible=input.type==='password';input.type=visible?'text':'password';button.setAttribute('aria-pressed',String(visible));button.setAttribute('aria-label',visible?'Ẩn mật khẩu':'Hiện mật khẩu');button.innerHTML=passwordEye(visible);});$('#resend-verify').onclick=async()=>{const email=screen.querySelector('[name=email]')?.value;if(!email)return $('#auth-message').textContent='Nhập email trước khi gửi lại.';try{$('#auth-message').textContent=(await requestAPI('resend','POST',{email})).message;$('#auth-message').dataset.state='success';}catch(e){$('#auth-message').textContent=e.message;$('#auth-message').dataset.state='error';}};$('#auth-form').onsubmit=async e=>{e.preventDefault();const button=e.target.querySelector('[type=submit]');button.disabled=true;try{const values=Object.fromEntries(new FormData(e.target));if(reset||verify)values.token=location.hash.split('=')[1];const result=await requestAPI(mode==='register'?'register':mode==='forgot'?'forgot':reset?'reset':verify?'verify':'login','POST',values);if(mode==='login'){await openAccount();}else if(reset||verify){history.replaceState(null,'','/');authScreen('login',result.message);}else {$('#auth-message').textContent=result.message;$('#auth-message').dataset.state='success';$('#auth-message').focus();const password=screen.querySelector('[name=password]');if(password){password.value='';password.type='password';const eye=screen.querySelector('.password-eye');eye.setAttribute('aria-pressed','false');eye.setAttribute('aria-label','Hiện mật khẩu');eye.innerHTML=passwordEye();}}}catch(error){$('#auth-message').textContent=error.message;$('#auth-message').dataset.state='error';}finally{button.disabled=false;}};}
function syncStatus(message,kind){
 const el=$('#save-state');if(!el)return;
 const text=String(message||'').replace(/^[●•⚠]\s*/,'');
 const state=kind||(/xung đột|từ chối|không hợp lệ|chưa lên|chưa lưu/i.test(text)?'error':/chờ kết nối|mất mạng|chờ mạng/i.test(text)?'offline':/đang đồng bộ|tiếp tục đồng bộ/i.test(text)?'pending':'saved');
 el.replaceChildren();
 const icon=document.createElement('span');icon.innerHTML=svgIcon(state==='saved'?'cloudCheck':'warning');
 const label=document.createElement('span');label.textContent=text;
 el.append(icon,label);
 el.setAttribute('role','status');el.dataset.sync=state;
 el.setAttribute('aria-label','Trạng thái đồng bộ: '+text);
 el.title=state==='pending'?'Đang gửi dữ liệu lên máy chủ':state==='saved'?'Dữ liệu đã được máy chủ xác nhận':'Dữ liệu hiện vẫn được giữ trên thiết bị';
}
function cacheCloud(){localStorage.setItem(KEY,JSON.stringify(data));localStorage.setItem(KEY+'-sync',JSON.stringify({revision:cloudRevision,dirty}));}
async function openAccount(){const me=await requestAPI('me');currentUser=me.user;startIdleSession(me.user.session_expires);KEY='zen-account-'+currentUser.id;const remote=await requestAPI('workspace');cloudRevision=remote.revision;dirty=false;syncConflict=false;syncBlocked=false;const cached=localStorage.getItem(KEY),meta=JSON.parse(localStorage.getItem(KEY+'-sync')||'{}');if(meta.dirty&&cached){const pending=JSON.parse(cached);if(valid(pending)){data=pending;cloudRevision=meta.revision;dirty=true;}}if(!dirty)data=remote.data;cacheCloud();document.body.classList.remove('signed-out');$('#auth-screen')?.remove();view='dashboard';active=null;query='';render();syncStatus(dirty?'● Đang đồng bộ…':'● Đã đồng bộ');renderAccountAvatar();if(dirty)await flushCloud();}
let syncAgain=false,invalidSyncNotified=false,syncBlocked=false;
async function flushCloud(manual=false){
 if(!currentUser||!dirty)return;
 if(syncConflict){syncStatus('⚠ Xung đột dữ liệu · Chưa ghi đè','error');return;}
 if(syncBlocked&&!manual){syncStatus('⚠ Chưa đồng bộ · Cần kiểm tra dữ liệu','error');return;}
 if(syncing){syncAgain=true;return;}
 if(!navigator.onLine){syncStatus('⚠ Đã lưu trên máy · Chờ kết nối','offline');return;}
 syncing=true;clearTimeout(syncTimer);
 const accountId=currentUser.id;
 const snapshot=JSON.stringify(data);
 let retry=false;
 try{
  const payload=JSON.parse(snapshot);
  if(!valid(payload)){
   syncBlocked=true;syncStatus('⚠ Dữ liệu không hợp lệ · Chưa đồng bộ','error');
   if(!invalidSyncNotified){notify('Ghi chú hoặc dữ liệu chưa hợp lệ. Bản cục bộ được giữ nguyên.');invalidSyncNotified=true;}
   return;
  }
  if(new TextEncoder().encode(JSON.stringify({data:payload,revision:cloudRevision})).length>1900000){
   syncBlocked=true;syncStatus('⚠ Dữ liệu quá lớn · Chưa đồng bộ','error');
   if(!invalidSyncNotified){notify('Bản dữ liệu vượt giới hạn đồng bộ. Hãy giảm dữ liệu nhúng hoặc xuất bản sao JSON.');invalidSyncNotified=true;}
   return;
  }
  syncStatus('● Đang đồng bộ…','pending');
  const response=await requestAPI('workspace','PUT',{data:payload,revision:cloudRevision});
  if(currentUser?.id!==accountId)return;
  cloudRevision=response.revision;
  dirty=JSON.stringify(data)!==snapshot;
  cacheCloud();
  invalidSyncNotified=false;syncBlocked=false;
  syncStatus(dirty?'● Đã lưu trên máy · Tiếp tục đồng bộ':'● Đã đồng bộ',dirty?'pending':'saved');
  retry=dirty;
 }catch(error){
  if(currentUser?.id!==accountId)return;
  if(error.status===409){
   syncConflict=true;
   syncStatus('⚠ Xung đột dữ liệu · Chưa ghi đè','error');
   notify('Có thay đổi từ thiết bị khác. Bản trên máy của bạn được giữ nguyên.');
  }else if([400,413,422].includes(error.status)){
   syncBlocked=true;
   syncStatus('⚠ Máy chủ từ chối dữ liệu · Chưa đồng bộ','error');
   if(!invalidSyncNotified){notify('Dữ liệu chưa được máy chủ chấp nhận. Bản nháp vẫn ở thiết bị.');invalidSyncNotified=true;}
  }else{
   retry=true;
   syncStatus('⚠ Đã lưu trên máy · Chờ kết nối','offline');
   if(error.status===401)notify('Phiên đăng nhập hết hạn. Bản nháp vẫn ở trên thiết bị.');
  }
 }finally{
  syncing=false;
  if(dirty&&!syncConflict&&!syncBlocked&&retry&&navigator.onLine&&currentUser?.id===accountId){
   clearTimeout(syncTimer);syncTimer=setTimeout(()=>flushCloud(),syncAgain?800:6000);
  }
  syncAgain=false;
 }
}
save=function(){
 if(!currentUser)return false;
 try{
  const wasDirty=dirty;
  dirty=true;
  cacheCloud();
  invalidSyncNotified=false;
  if(syncConflict){syncStatus('⚠ Xung đột dữ liệu · Chưa ghi đè','error');return true;}
  if(syncBlocked){syncStatus('⚠ Bản nháp đã lưu · Chưa đồng bộ','error');return true;}
  syncStatus(navigator.onLine?'● Đã lưu trên máy · Đang đồng bộ':'⚠ Đã lưu trên máy · Chờ kết nối',navigator.onLine?'pending':'offline');
  clearTimeout(syncTimer);
  syncTimer=setTimeout(()=>flushCloud(),750);
  return true;
 }catch{
  syncStatus('⚠ Không thể lưu bản nháp trên máy','error');
  notify('Bộ nhớ cục bộ không thể lưu. Hãy xuất bản sao JSON.');
  return false;
 }
};
async function pollCloud(){if(document.hidden||!currentUser||dirty||syncing||$('#editor').open||typeof ganttPointer!=='undefined'&&ganttPointer)return;try{const requestedRevision=cloudRevision;const remote=await requestAPI('workspace?revision='+requestedRevision);if(dirty||syncing||$('#editor').open||typeof ganttPointer!=='undefined'&&ganttPointer||requestedRevision!==cloudRevision)return;if(!remote.unchanged&&remote.revision!==cloudRevision){data=remote.data;cloudRevision=remote.revision;cacheCloud();render();syncStatus('● Đã cập nhật từ thiết bị khác');}}catch{syncStatus('⚠ Chờ kết nối');}}
function accountPanel(){if(!currentUser)return;modal(`<h2>Settings <small>Cài đặt tài khoản</small></h2><section class="profile-card"><h3>Hồ sơ cá nhân</h3><p class="help-copy">Thông tin được lưu riêng theo tài khoản của bạn.</p><img id="profile-preview" alt="Ảnh đại diện" width="72" height="72" ${currentUser.avatar?'src="'+esc(currentUser.avatar)+'"':'hidden'}><label>Tên hiển thị<input id="profile-name" maxlength="100" value="${esc(currentUser.name||'')}" autocomplete="name"></label><label>Ngày sinh<input id="profile-birthday" type="date" max="${new Date().toISOString().slice(0,10)}" value="${esc(currentUser.birthday||'')}" autocomplete="bday"></label><label>Ảnh đại diện<input id="profile-photo" type="file" accept="image/png,image/jpeg,image/webp"></label><small>PNG, JPG hoặc WebP · tối đa 5 MB · tự thu nhỏ khi lưu.</small><div class="help-actions"><button class="btn primary" type="button" id="save-profile">Lưu hồ sơ</button><button class="btn" type="button" id="remove-photo">Xóa ảnh</button></div><p id="profile-status" role="status"></p></section><h3 class="settings-section">Tài khoản & bảo mật</h3><p>${esc(currentUser.email)}</p><p class="help-copy">Đồng bộ tự động khi chỉnh sửa. Thiết bị khác nhận cập nhật sau khoảng 10 giây khi đang mở; kết nối lại sẽ gửi dữ liệu chờ.</p><h3 class="settings-section">Thông báo</h3><label class="check-row"><input id="email-reminder" type="checkbox" ${currentUser.email_reminders?'checked':''}><span>Nhận email khi có việc đến hạn hoặc quá hạn.</span></label><div class="profile-card reminder-options"><label>Giờ gửi (Việt Nam)<select id="reminder-hour">${Array.from({length:24},(_,h)=>`<option value="${h}" ${h===(currentUser.reminder_hour??8)?'selected':''}>${String(h).padStart(2,'0')}:00</option>`).join('')}</select></label><label>Tần suất<select id="reminder-days">${[1,2,3,7].map(d=>`<option value="${d}" ${d===(currentUser.reminder_days??1)?'selected':''}>${d===1?'Mỗi ngày':d===7?'Mỗi tuần':'Mỗi '+d+' ngày'}</option>`).join('')}</select></label><small>Áp dụng cho email và thông báo trình duyệt. Chu kỳ tính từ lần gửi thành công gần nhất; chỉ gửi khi có việc cần nhắc.</small><button class="btn primary" type="button" id="save-reminders">Lưu lịch thông báo</button><p id="reminder-status" role="status"></p></div><div class="help-actions"><button class="btn" type="button" id="enable-push">Bật thông báo trình duyệt</button><button class="btn" type="button" id="disable-push">Tắt thông báo thiết bị này</button><h3 class="settings-section settings-full">Dữ liệu & đồng bộ</h3><button class="btn" type="button" id="sync-now">Đồng bộ ngay</button>${legacyData?'<button class="btn" type="button" id="import-legacy">Nhập dữ liệu cũ trên máy</button>':''}<button class="btn" type="button" data-action="export">Xuất bản sao JSON</button><button class="btn" type="button" data-action="import">Nhập JSON</button><button class="btn" type="button" data-action="undo" ${undoData?'':'disabled'}>Hoàn tác lần xóa</button><button class="btn danger" type="button" data-action="clear">Xóa dữ liệu</button>${syncConflict?'<button class="btn danger" type="button" id="resolve-cloud">Dùng bản trên máy chủ</button>':''}<button class="btn danger" type="button" id="sign-out">Đăng xuất</button></div><p class="help-copy" style="margin-top:15px">Thông báo cần được bạn cho phép. Trình duyệt có thể giới hạn thông báo khi bị đóng hoàn toàn. Email nhắc việc có thể tắt bất cứ lúc nào.</p>`,null,true);$('#editor').classList.add('account-dialog');$('#editor').addEventListener('close',()=>$('#editor').classList.remove('account-dialog'),{once:true});let profileAvatar=currentUser.avatar||'';$('#remove-photo').onclick=()=>{profileAvatar='';$('#profile-preview').hidden=true;$('#profile-photo').value='';};$('#profile-photo').onchange=async e=>{const file=e.target.files[0];if(!file)return;try{if(file.size>5*1024*1024||!['image/png','image/jpeg','image/webp'].includes(file.type))throw Error('Chọn ảnh PNG, JPG, WebP dưới 5 MB.');const bitmap=await createImageBitmap(file),canvas=document.createElement('canvas');canvas.width=canvas.height=192;const ctx=canvas.getContext('2d'),size=Math.min(bitmap.width,bitmap.height);ctx.drawImage(bitmap,(bitmap.width-size)/2,(bitmap.height-size)/2,size,size,0,0,192,192);bitmap.close();profileAvatar=canvas.toDataURL('image/webp',.8);$('#profile-preview').src=profileAvatar;$('#profile-preview').hidden=false;}catch(error){$('#profile-status').textContent=error.message;}};$('#save-profile').onclick=async e=>{e.target.disabled=true;try{const profile=await requestAPI('profile','PUT',{name:$('#profile-name').value,birthday:$('#profile-birthday').value,avatar:profileAvatar});Object.assign(currentUser,profile);renderAccountAvatar();$('#profile-status').textContent='Đã lưu hồ sơ. Các thiết bị khác nhận thông tin khi đăng nhập lại.';}catch(error){$('#profile-status').textContent=error.message;}finally{e.target.disabled=false;}};$('#save-reminders').onclick=async e=>{e.target.disabled=true;try{const hour=Number($('#reminder-hour').value),days=Number($('#reminder-days').value);await requestAPI('preferences','PUT',{emailReminders:$('#email-reminder').checked,hour,days});Object.assign(currentUser,{reminder_hour:hour,reminder_days:days});$('#reminder-status').textContent='Đã lưu lịch thông báo.';}catch(error){$('#reminder-status').textContent=error.message;}finally{e.target.disabled=false;}};$('#email-reminder').onchange=async e=>{try{await requestAPI('preferences','PUT',{emailReminders:e.target.checked});currentUser.email_reminders=e.target.checked?1:0;notify('Đã lưu cài đặt email.');}catch(error){e.target.checked=!e.target.checked;notify(error.message);}};$('#enable-push').onclick=enablePush;$('#disable-push').onclick=async()=>{try{const reg=await navigator.serviceWorker.ready,sub=await reg.pushManager.getSubscription();if(sub){await requestAPI('push','DELETE',{endpoint:sub.endpoint});await sub.unsubscribe();}notify('Đã tắt thông báo trên thiết bị này.');}catch(e){notify(e.message);}};$('#sync-now').onclick=async()=>{syncBlocked=false;await flushCloud(true);await pollCloud();notify(syncConflict?'Cần xử lý xung đột dữ liệu.':dirty?'Đang chờ đồng bộ.':'Dữ liệu đã cập nhật.');};$('#import-legacy')?.addEventListener('click',()=>modal('<h2>Nhập dữ liệu cũ?</h2><p>Thao tác thêm dự án cũ vào tài khoản này; không xóa dữ liệu đang có. Nhập nhiều lần sẽ tạo các bản sao.</p>',()=>{try{const old=JSON.parse(legacyData);if(!valid(old))throw Error('Dữ liệu cũ không hợp lệ.');for(const p of old.projects){p.id=uid();for(const t of p.tasks){t.id=uid();t.checks.forEach(c=>c.id=uid());}}if(data.projects.length+old.projects.length>100)throw Error('Vượt giới hạn 100 dự án.');data.projects.push(...old.projects);save();render();$('#editor').close();notify('Đã nhập dữ liệu cũ vào tài khoản.');}catch(e){notify(e.message);}}));$('#resolve-cloud')?.addEventListener('click',()=>modal('<h2>Dùng dữ liệu trên máy chủ?</h2><p>Bản chỉnh sửa hiện tại vẫn được lưu thành bản sao trên máy. Bạn nên xuất JSON trước khi tiếp tục. Thao tác này thay bảng đang hiển thị bằng dữ liệu máy chủ.</p>',async()=>{localStorage.setItem(KEY+'-conflict-'+Date.now(),JSON.stringify(data));try{const remote=await requestAPI('workspace');data=remote.data;cloudRevision=remote.revision;dirty=false;syncConflict=false;syncBlocked=false;cacheCloud();$('#editor').close();render();syncStatus('● Đã đồng bộ');}catch(e){notify('Chưa lấy được dữ liệu máy chủ. Bản chỉnh sửa của bạn vẫn được giữ.');}}));$('#sign-out').onclick=()=>modal('<h2>Đăng xuất tài khoản?</h2><p class="help-copy">Đồng bộ các thay đổi trước khi rời không gian làm việc.</p>',()=>signOutAccount(false));const logout=$('#sign-out'),section=document.createElement('section');section.className='settings-signout';section.innerHTML='<h3>Phiên đăng nhập</h3><p>Giữ đăng nhập khi tải lại trang. Tự khóa sau 10 phút không thao tác.</p>';$('#editor-body').append(section);section.append(logout);}

async function enablePush(){try{if(!('serviceWorker'in navigator)||!('PushManager'in window)||!('Notification'in window))throw Error('Trình duyệt chưa hỗ trợ Web Push. Hãy dùng email nhắc việc.');if(await Notification.requestPermission()!=='granted')throw Error('Chưa được cấp quyền thông báo.');await navigator.serviceWorker.register('/sw.js');const reg=await navigator.serviceWorker.ready;let sub=await reg.pushManager.getSubscription();if(!sub){const {key}=await requestAPI('push-key');const raw=atob(key.replace(/-/g,'+').replace(/_/g,'/'));sub=await reg.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:Uint8Array.from(raw,c=>c.charCodeAt(0))});}await requestAPI('push','POST',{endpoint:sub.endpoint});notify('Đã bật thông báo nhắc việc hằng ngày trên thiết bị này.');}catch(e){notify(e.message);}}
document.querySelectorAll('.top-actions>.avatar').forEach(b=>{b.removeAttribute('data-action');b.onclick=accountPanel;});const accountButton=document.createElement('button');accountButton.className='nav';accountButton.innerHTML=svgIcon('settings')+' Settings';accountButton.setAttribute('aria-label','Settings — Cài đặt tài khoản');accountButton.onclick=()=>{$('.sidebar').classList.remove('open');accountPanel();};document.querySelector('#settings-slot').append(accountButton);
window.addEventListener('online',()=>flushCloud());document.addEventListener('visibilitychange',()=>{if(!document.hidden){flushCloud();pollCloud();}});setInterval(()=>{if(navigator.onLine){if(dirty)flushCloud();else pollCloud();}},10000);window.addEventListener('focus',()=>{if(dirty)flushCloud();else pollCloud();});
let idleTimer,activityInFlight=false,lastActivitySent=0,sessionDeadline=0;
function startIdleSession(deadline){sessionDeadline=Number(deadline)||Date.now()+600000;clearTimeout(idleTimer);idleTimer=setTimeout(()=>signOutAccount(true),Math.max(0,sessionDeadline-Date.now()));}
async function touchSession(){if(!currentUser||document.hidden||activityInFlight)return;if(Date.now()>=sessionDeadline)return signOutAccount(true);if(Date.now()-lastActivitySent<30000)return;activityInFlight=true;lastActivitySent=Date.now();try{const result=await requestAPI('activity','POST',{});startIdleSession(result.expires);}catch(e){if(e.status===401)signOutAccount(true);}finally{activityInFlight=false;}}
async function signOutAccount(automatic=false){if(!currentUser)return;try{if(automatic){try{const me=await requestAPI('me');if(me.user.id===currentUser.id&&me.user.session_expires>Date.now()){startIdleSession(me.user.session_expires);return;}}catch{}}if(!automatic){await flushCloud();if(dirty){notify('Còn dữ liệu chưa đồng bộ. Hãy xuất JSON hoặc chờ đồng bộ trước khi đăng xuất.');return;}await requestAPI('logout','POST',{});}else{if(dirty)cacheCloud();requestAPI('logout','POST',{}).catch(()=>{});}clearTimeout(idleTimer);clearTimeout(syncTimer);currentUser=null;data={schema:1,projects:[],notes:[]};document.querySelectorAll('dialog[open]').forEach(d=>d.close());$('#main').innerHTML='';$('#side-projects').innerHTML='';$('#tabs').innerHTML='';authScreen('login',automatic?'Đã khóa sau 10 phút không thao tác. Đăng nhập để tiếp tục; bản thay đổi chưa gửi được giữ trên thiết bị.':'Đã đăng xuất tài khoản.');}catch(e){notify(e.message);}}
for(const event of ['pointerdown','keydown','input','wheel','touchstart'])document.addEventListener(event,()=>touchSession(),{passive:true});
document.addEventListener('visibilitychange',()=>{if(!document.hidden&&currentUser&&Date.now()>=sessionDeadline)signOutAccount(true);});
(async()=>{const shared=new URLSearchParams(location.search).get('boardshare');if(shared){try{const r=await requestAPI('shared/'+shared);data=r.data;contentReadOnly=true;document.body.classList.remove('signed-out');noteBoard='';view='notes';render();}catch(e){authScreen('login',e.message);}return;}if('serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});const mode=location.hash.startsWith('#reset=')?'reset':location.hash.startsWith('#verify=')?'verify':null;if(mode)return authScreen(mode);try{await openAccount();}catch(error){currentUser=null;authScreen('login',error.status===401?'':error.message+' · Phiên đăng nhập vẫn được giữ. Thử tải lại khi có mạng.');}})();

function passwordEye(visible=false){return '<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M2 12s3.5-7 10-7 10 7 10 7-3.5 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>'+(visible?'<path d="m3 3 18 18"/>':'')+'</svg>';}
function passwordField(isNew){return '<label class="field" for="account-password">Mật khẩu</label><div class="password-wrap"><input id="account-password" name="password" type="password" minlength="'+(isNew?'10':'1')+'" maxlength="128" autocomplete="'+(isNew?'new-password':'current-password')+'" required><button type="button" class="password-eye" aria-label="Hiện mật khẩu" aria-pressed="false" aria-controls="account-password">'+passwordEye()+'</button></div>';}

function renderAccountAvatar(){const name=currentUser?.name?.trim()||currentUser?.email||'Bạn',initials=currentUser?.name?.trim()?name.split(/\s+/).filter(Boolean).map(w=>Array.from(w)[0]).filter((_,i,a)=>i===0||i===a.length-1).join('').toUpperCase():name.slice(0,2).toUpperCase();document.querySelectorAll('.avatar').forEach(el=>{el.textContent=initials;el.title='Tài khoản · '+name;if(el.tagName==='BUTTON')el.setAttribute('aria-label','Mở cài đặt tài khoản của '+name);el.classList.remove('has-photo');if(currentUser?.avatar){const img=document.createElement('img');img.alt='';img.src=currentUser.avatar;img.onerror=()=>{el.textContent=initials;el.classList.remove('has-photo');};el.textContent='';el.append(img);el.classList.add('has-photo');}});}
